tokens.css:
--color-bg: #fffdfa;
--color-surface: #f7f4f0;
--color-text: #1c1a18;
--color-text-muted: #6b645c;
--color-border: #e4ded6;
--color-primary: #666666;
--color-on-primary: #ffffff;
--color-accent: #b5532f;
--color-on-accent: #ffffff;
--font-display: "Cormorant Garamond", Georgia, serif;
--font-body: "Hanken Grotesk", system-ui, sans-serif;
--text-sm: 14px;
--text-base: 17px;
--text-lg: 21px;
--text-xl: 27px;
--text-2xl: 33px;
--text-3xl: 42px;
--radius-control: 4px;
--radius-card: 6px;
--space-section: 96px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
